/* Helper to get ASCII glyph */
inline const uint8_t* get_ascii_glyph(char ch) {
    if ((unsigned char)ch < 0x20 || (unsigned char)ch > 0x7E) return ascii_8x16[0];
    return ascii_8x16[(unsigned char)ch - 0x20];
}

/* Helper to get Chinese glyph */
inline const uint8_t* get_chinese_glyph(const char* utf8Char) {
    for (int i = 0; i < chinese_font_count; i++) {
        if (std::strncmp(chinese_font_table[i].utf8, utf8Char, 3) == 0)
            return chinese_font_table[i].glyph;
    }
    return nullptr;
}

/* Helper: compute string pixel width (ASCII=8px, Chinese=16px) */
inline int get_str_pixel_width(const char* utf8) {
    int w = 0;
    while (*utf8) {
        unsigned char c = (unsigned char)*utf8;
        if (c < 0x80) { w += 8; utf8 += 1; }
        else if ((c & 0xE0) == 0xC0) { w += 8; utf8 += 2; }
        else if ((c & 0xF0) == 0xE0) { w += 16; utf8 += 3; }
        else { w += 16; utf8 += 4; }
    }
    return w;
}
